export class InvalidRequestError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'InvalidRequestError';
  }
}

/** Extracts typed fields from untrusted request bodies and query strings. */
export class RequestParser {
  private readonly source: Record<string, unknown>;

  constructor(raw: unknown, private readonly location: string) {
    this.source = typeof raw === 'object' && raw !== null ? (raw as Record<string, unknown>) : {};
  }

  requiredString(field: string): string {
    const value = this.optionalString(field);
    if (value === undefined) {
      throw new InvalidRequestError(`${this.location} field "${field}" is required`);
    }
    return value;
  }

  optionalString(field: string): string | undefined {
    const value = this.source[field];
    if (value === undefined || value === null) {
      return undefined;
    }
    if (typeof value !== 'string') {
      throw new InvalidRequestError(`${this.location} field "${field}" must be a string`);
    }
    return value;
  }
}

